ROUTE("/api/admin/orders/<int>/status").methods(crow::HTTPMethod::PUT)([](const crow::request&r,int id){std::lock_guard<std::mutex> lock(mu);if(!admin(who(r)))return err(403,"Admin required");auto j=crow::json::load(r.body);if(!j)return err(400,"Invalid JSON");auto status=field(j,"status");
if(status!="Pending"&&status!="Confirmed"&&status!="Preparing"&&status!="Ready"&&status!="Completed"&&status!="Cancelled")return err(400,"Invalid status");St find("SELECT user_id,status FROM orders WHERE id=?");find.b(1,(long long)id);if(!find.next())return err(404,"Order not found");auto old=find.str(1);if(old=="Completed"||old=="Cancelled")return err(409,"Finalized order cannot change");St s("UPDATE orders SET status=? WHERE id=?");s.b(1,status);s.b(2,(long long)id);s.next();notice(find.num(0),"Order updated","Order #"+std::to_string(id)+" is now "+status);J o;o["ok"]=true;return reply(200,o);});
