ROUTE("/api/admin/analytics")([](const crow::request&r){std::lock_guard<std::mutex> lock(mu);if(!admin(who(r)))return err(403,"Admin required");J j;St s("SELECT (SELECT COUNT(*) FROM users WHERE role='customer'),(SELECT COUNT(*) FROM foods WHERE active=1),(SELECT COUNT(*) FROM orders),(SELECT COUNT(*) FROM orders WHERE status='Pending'),(SELECT COALESCE(SUM(total_minor),0) FROM orders WHERE status='Completed')");s.next();j["customers"]=s.num(0);j["foods"]=s.num(1);j["orders"]=s.num(2);j["pending"]=s.num(3);j["completed_value_minor"]=s.num(4);St m("SELECT strftime('%Y-%m',created_at) month,COUNT(*) count,COALESCE(SUM(CASE WHEN status='Completed' THEN total_minor ELSE 0 END),0) value_minor FROM orders GROUP BY strftime('%Y-%m',created_at) ORDER BY month");j["monthly"]=rows(m,3);return reply(200,j);});
